components.css:
.ds-specimen { font-family: DM Sans, Avenir Next, system-ui, sans-serif; color: var(--slate-12, #1c2024); }
.ds-playroom-install{
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 48px;
  gap: 12px;
  font-size: 12px;
}
.ds-playroom-install{
  padding: 12px 16px;
  background: var(--grass-9, #46a758);
  color: var(--grass-1, #fbfefb);
  border-radius: 4px;
}
.ds-playroom-install{
  background: var(--grass-11, #2a7e3b);
  color: #fbfefb;
}
.ds-specimen :focus-visible { outline: 2px solid var(--grass-8, #65ba74); outline-offset: 3px; }
@media (prefers-reduced-motion: reduce) { .ds-specimen * { animation: none !important; transition: none !important; } }

.ds-specimen { font-family: DM Sans, Avenir Next, system-ui, sans-serif; color: var(--slate-12, #1c2024); }
.ds-playroom-games{
  display: grid;
}
.ds-playroom-games button{
  display: flex;
  gap: 12px;
  align-items: center;
  min-height: 94px;
  padding: 16px 10px;
  text-align: left;
  border: 0;
  border-bottom: 0.5px solid var(--slate-6, #d9d9e0);
  background: transparent;
  cursor: pointer;
}
.ds-playroom-games button:hover{
  background: var(--grass-3, #e9f6e9);
}
.ds-playroom-games button[aria-pressed="true"]{
  background: var(--grass-4, #daf1db);
}
.ds-playroom-games img{
  width: 48px;
  height: 48px;
  border-radius: 8px;
}
.ds-playroom-games strong{
  display: block;
  font-size: 16px;
  line-height: 1.3;
}
.ds-playroom-games small{
  display: block;
  margin-top: 6px;
  font-size: 12px;
  color: var(--slate-11, #60646c);
}
.ds-playroom-games svg{
  flex-shrink: 0;
}
.ds-playroom-games button > span{
  flex: 1;
}
.ds-playroom-games{
    order: 0;
    display: flex;
    overflow: auto;
    padding: 12px 0;
  }
.ds-playroom-games button{
    flex: 0 0 190px;
    padding: 12px;
    min-height: 80px;
    border: 0;
  }
.ds-playroom-games img{
    width: 40px;
    height: 40px;
  }
.ds-playroom-games button > svg{
    display: none;
  }
.ds-specimen :focus-visible { outline: 2px solid var(--grass-8, #65ba74); outline-offset: 3px; }
@media (prefers-reduced-motion: reduce) { .ds-specimen * { animation: none !important; transition: none !important; } }

.ds-specimen { font-family: DM Sans, Avenir Next, system-ui, sans-serif; color: var(--slate-12, #1c2024); }
.ds-playroom-surface{
  background: var(--grass-3, #e9f6e9);
  padding: 24px 32px;
  min-width: 0;
}
.ds-playroom-surface{
    padding: 20px;
  }
.ds-playroom-surface{
    order: 1;
    padding: 20px 12px;
  }
.ds-specimen :focus-visible { outline: 2px solid var(--grass-8, #65ba74); outline-offset: 3px; }
@media (prefers-reduced-motion: reduce) { .ds-specimen * { animation: none !important; transition: none !important; } }

.ds-specimen { font-family: DM Sans, Avenir Next, system-ui, sans-serif; color: var(--slate-12, #1c2024); }
.ds-playroom-game-info{
  padding-top: 48px;
}
.ds-playroom-game-info h2{
  font-size: 24px;
  line-height: 1.25;
}
.ds-playroom-game-info p{
  color: var(--slate-11, #60646c);
  font-size: 16px;
  margin: 16px 0 24px;
  line-height: 1.6;
}
.ds-playroom-game-info{
    order: 2;
    padding: 24px 0;
  }
.ds-specimen :focus-visible { outline: 2px solid var(--grass-8, #65ba74); outline-offset: 3px; }
@media (prefers-reduced-motion: reduce) { .ds-specimen * { animation: none !important; transition: none !important; } }

.ds-specimen { font-family: DM Sans, Avenir Next, system-ui, sans-serif; color: var(--slate-12, #1c2024); }
.ds-playroom-notes{
  width: min(1320px, calc(100% - 64px));
  margin-inline: auto;
}
.ds-playroom-notes{
  padding-block: 48px;
}
.ds-playroom-notes > div{
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 20px;
}
.ds-playroom-notes > a{
  display: grid;
  grid-template-columns: 180px 1fr auto;
  gap: 24px;
  padding: 24px 0;
  align-items: center;
  border-top: 0.5px solid var(--slate-6, #d9d9e0);
}
.ds-playroom-notes > a > span{
  color: var(--slate-11, #60646c);
  font-size: 12px;
}
.ds-playroom-notes h3{
  font-size: 16px;
  font-weight: 500;
}
.ds-playroom-notes > div a{
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 44px;
  color: var(--grass-11, #2a7e3b);
  font-size: 12px;
}
.ds-playroom-notes{
    width: calc(100% - 40px);
  }
.ds-playroom-notes > a{
    grid-template-columns: 1fr auto;
    gap: 12px;
  }
.ds-playroom-notes > a > span{
    grid-column: 1 / -1;
  }
.ds-playroom-notes h2{
    font-size: 24px;
  }
.ds-specimen :focus-visible { outline: 2px solid var(--grass-8, #65ba74); outline-offset: 3px; }
@media (prefers-reduced-motion: reduce) { .ds-specimen * { animation: none !important; transition: none !important; } }
